/**
 * Whether the device can show a PiP window at all, independent of the user's
 * preference — what the code paths that want to *announce* the feature (a
 * notice, a settings row) should consult.
 */
internal fun pipSupported(context: Context): Boolean =
    Build.VERSION.SDK_INT >= Build.VERSION_CODES.O &&
        runCatching {
            context.packageManager.hasSystemFeature(PackageManager.FEATURE_PICTURE_IN_PICTURE)
        }.getOrDefault(false)

